package greeter

import "strings"

// Slug 把一段文本折成 URL 友好的短名：去首尾空白、连续空白折成一个连字符、
// 转小写。纯空白返回空串。
func Slug(s string) string {
	return strings.ToLower(strings.Join(strings.Fields(s), "-"))
}

package greeter

import "testing"

func TestSlug(t *testing.T) {
	if got := Slug("Hello World"); got != "hello-world" {
		t.Fatalf("Slug(Hello World) = %q", got)
	}
	if got := Slug("  Hello World  "); got != "hello-world" {
		t.Fatalf("Slug(trimmed) = %q", got)
	}
	if got := Slug("a   b"); got != "a-b" {
		t.Fatalf("Slug(collapse) = %q", got)
	}
}

package greeter

import "strings"

// JoinSlug 把若干段文本各自 Slug 后用 "/" 连起来。空串与纯空白段被跳过。
func JoinSlug(parts ...string) string {
	slugs := make([]string, 0, len(parts))
	for _, p := range parts {
		if s := Slug(p); s != "" {
			slugs = append(slugs, s)
		}
	}
	return strings.Join(slugs, "/")
}

package greeter

import "testing"

func TestJoinSlug(t *testing.T) {
	if got := JoinSlug("Hello World", "Big Day"); got != "hello-world/big-day" {
		t.Fatalf("JoinSlug(two) = %q", got)
	}
	if got := JoinSlug("a", "", "b"); got != "a/b" {
		t.Fatalf("JoinSlug(skip empty) = %q", got)
	}
	if got := JoinSlug("a", "   ", "b"); got != "a/b" {
		t.Fatalf("JoinSlug(skip blank) = %q", got)
	}
}
